</script>
<div class="table-scroll" tabindex="-1" role="region" aria-label="Timeline relative-unit table">
  <table><caption>Relative effort units, not dates. Trace and inspection are separate actions.</caption><thead><tr><th>Task</th><th>Title</th><th>Status</th><th>Spec group</th><th>Start</th><th>End</th><th>Effort</th><th>Relationship</th><th>Trace</th></tr></thead><tbody>
